"use client";

import * as React from "react";
import { Pin, PinOff, Search } from "lucide-react";

type DivProps = React.ComponentProps<"div">;

export type RailPanelContext = {
  id: string;
  pinned: boolean;
  peeking: boolean;
  query: string;
  closePeek: () => void;
};

export type RailPanelSection = {
  id: string;
  label: string;
  icon: React.ReactNode;
  panel: React.ReactNode | ((context: RailPanelContext) => React.ReactNode);
  badge?: React.ReactNode;
  searchPlaceholder?: string;
};

export type RailPanelSidebarProps = DivProps & {
  sections: RailPanelSection[];
  activeId?: string;
  defaultActiveId?: string;
  onActiveChange?: (id: string) => void;
  pinned?: boolean;
  defaultPinned?: boolean;
  onPinnedChange?: (pinned: boolean) => void;
  peeking?: boolean;
  onPeekingChange?: (peeking: boolean) => void;
  brand?: React.ReactNode;
  footer?: React.ReactNode;
  width?: { rail?: number; panel?: number };
  search?: boolean;
  peekDelay?: number;
  labels?: { sidebar?: string; sections?: string; pin?: string; search?: string };
  children?: React.ReactNode;
};

type Transient = null | "collapsing" | "expanding-closed" | "expanding-peek" | "peek-closing";
type Leaving = null | { id: string; direction: 1 | -1 };

const EASE = "cubic-bezier(0.45, 0, 0.2, 1)";
const EASE_OUT = "cubic-bezier(0.22, 1, 0.36, 1)";
const SLIDE_MS = 240;
const SWAP_IN_MS = 220;
const SWAP_OUT_MS = 160;
const FOLD_MS = 260;
const PEEK_MS = 180;
const SWAP_SHIFT = 16;

function useReducedMotion() {
  const [reduced, setReduced] = React.useState(true);
  React.useEffect(() => {
    const media = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setReduced(media.matches);
    update();
    media.addEventListener("change", update);
    return () => media.removeEventListener("change", update);
  }, []);
  return reduced;
}

function canAnimate(node: Element | null): node is HTMLElement {
  return node instanceof HTMLElement && typeof node.animate === "function";
}

export function RailPanelSidebar({
  sections,
  activeId,
  defaultActiveId,
  onActiveChange,
  pinned: pinnedProp,
  defaultPinned = true,
  onPinnedChange,
  peeking: peekingProp,
  onPeekingChange,
  brand,
  footer,
  width,
  search = true,
  peekDelay = 150,
  labels,
  children,
  className = "",
  style,
  ref,
  ...rest
}: RailPanelSidebarProps) {
  const reduced = useReducedMotion();
  const baseId = React.useId();
  const titleId = `${baseId}-title`;
  const railWidth = width?.rail ?? 56;
  const panelWidth = width?.panel ?? 248;
  const firstId = sections[0]?.id ?? "";

  const [localActive, setLocalActive] = React.useState(defaultActiveId ?? firstId);
  const [localPinned, setLocalPinned] = React.useState(defaultPinned);
  const [localPeek, setLocalPeek] = React.useState(false);
  const [query, setQuery] = React.useState("");
  const [transient, setTransient] = React.useState(null as Transient);
  const [leaving, setLeaving] = React.useState(null as Leaving);

  const active = activeId ?? localActive;
  const pinned = pinnedProp ?? localPinned;
  const rawPeek = peekingProp ?? localPeek;
  const peeking = !pinned && rawPeek;
  const activeIndex = Math.max(0, sections.findIndex((section) => section.id === active));
  const activeSection = sections[activeIndex];
  const leavingSection = leaving ? sections.find((section) => section.id === leaving.id) : undefined;

  const asideRef = React.useRef(null as HTMLElement | null);
  const listRef = React.useRef(null as HTMLDivElement | null);
  const indicatorRef = React.useRef(null as HTMLSpanElement | null);
  const spacerRef = React.useRef(null as HTMLDivElement | null);
  const slotRef = React.useRef(null as HTMLDivElement | null);
  const shadowRef = React.useRef(null as HTMLDivElement | null);
  const bodyRef = React.useRef(null as HTMLDivElement | null);
  const buttonRefs = React.useRef({} as { [id: string]: HTMLButtonElement | null });
  const slideAnimation = React.useRef(null as Animation | null);
  const foldAnimations = React.useRef([] as Animation[]);
  const closeTimer = React.useRef(0);
  const previousActive = React.useRef(active);
  const previousContent = React.useRef(active);
  const previousPinned = React.useRef(pinned);
  const previousPeek = React.useRef(peeking);
  const peekRef = React.useRef(peeking);
  const latest = React.useRef({ pinned, rawPeek, peekingProp, onPeekingChange });
  latest.current = { pinned, rawPeek, peekingProp, onPeekingChange };

  const clearCloseTimer = () => {
    if (closeTimer.current) window.clearTimeout(closeTimer.current);
    closeTimer.current = 0;
  };

  const commitPeek = (next: boolean) => {
    const state = latest.current;
    if (next && state.pinned) return;
    if (state.rawPeek === next) return;
    if (state.peekingProp === undefined) setLocalPeek(next);
    state.onPeekingChange?.(next);
  };

  const openPeek = () => {
    clearCloseTimer();
    commitPeek(true);
  };

  const closePeek = () => {
    clearCloseTimer();
    commitPeek(false);
  };

  // The peek stays while the pointer travels from the rail into the panel; it retracts only after a short grace period.
  const scheduleClose = () => {
    clearCloseTimer();
    closeTimer.current = window.setTimeout(() => {
      closeTimer.current = 0;
      commitPeek(false);
    }, peekDelay);
  };

  const selectSection = (next: string) => {
    if (next === active) return;
    if (activeId === undefined) setLocalActive(next);
    onActiveChange?.(next);
  };

  const setPinnedState = (next: boolean) => {
    if (next === pinned) return;
    if (pinnedProp === undefined) setLocalPinned(next);
    onPinnedChange?.(next);
    if (next) {
      clearCloseTimer();
      if (peekingProp === undefined) setLocalPeek(false);
      if (rawPeek) onPeekingChange?.(false);
    }
  };

  const placeIndicator = (button: HTMLButtonElement) => {
    const indicator = indicatorRef.current;
    if (!indicator) return;
    indicator.style.transform = `translateY(${button.offsetTop}px)`;
    indicator.style.height = `${button.offsetHeight}px`;
  };

  React.useLayoutEffect(() => {
    const fromId = previousActive.current;
    previousActive.current = active;
    const to = buttonRefs.current[active];
    const indicator = indicatorRef.current;
    if (!to || !indicator) return;
    const from = fromId === active ? null : buttonRefs.current[fromId];
    placeIndicator(to);
    if (!from || reduced || !canAnimate(indicator)) return;
    slideAnimation.current?.cancel();
    slideAnimation.current = indicator.animate(
      [{ transform: `translateY(${from.offsetTop}px)` }, { transform: `translateY(${to.offsetTop}px)` }],
      { duration: SLIDE_MS, easing: EASE },
    );
  }, [active]);

  React.useLayoutEffect(() => {
    const fromId = previousContent.current;
    previousContent.current = active;
    if (fromId === active) return;
    setQuery("");
    const fromIndex = sections.findIndex((section) => section.id === fromId);
    const direction: 1 | -1 = activeIndex > fromIndex ? 1 : -1;
    if (reduced) {
      setLeaving(null);
      return;
    }
    const entering = bodyRef.current?.querySelector("[data-entering]") ?? null;
    if (canAnimate(entering)) {
      entering.animate(
        [{ opacity: 0, transform: `translateY(${direction * SWAP_SHIFT}px)` }, { opacity: 1, transform: "translateY(0)" }],
        { duration: SWAP_IN_MS, easing: EASE_OUT },
      );
    }
    const title = slotRef.current?.querySelector("[data-title]") ?? null;
    if (canAnimate(title)) {
      title.animate(
        [{ opacity: 0, transform: `translateY(${direction * 6}px)` }, { opacity: 1, transform: "translateY(0)" }],
        { duration: SWAP_IN_MS, easing: EASE_OUT },
      );
    }
    if (fromIndex >= 0) setLeaving({ id: fromId, direction });
  }, [active]);

  React.useLayoutEffect(() => {
    if (!leaving) return;
    const node = bodyRef.current?.querySelector("[data-leaving]") ?? null;
    if (!canAnimate(node)) {
      setLeaving(null);
      return;
    }
    let settled = false;
    const animation = node.animate(
      [{ opacity: 1, transform: "translateY(0)" }, { opacity: 0, transform: `translateY(${-leaving.direction * SWAP_SHIFT}px)` }],
      { duration: SWAP_OUT_MS, easing: EASE, fill: "forwards" },
    );
    animation.onfinish = () => {
      settled = true;
      setLeaving(null);
    };
    return () => {
      if (!settled) animation.cancel();
    };
  }, [leaving]);

  const cancelFold = () => {
    for (const animation of foldAnimations.current) animation.cancel();
    foldAnimations.current = [];
  };

  React.useLayoutEffect(() => {
    const was = previousPinned.current;
    previousPinned.current = pinned;
    if (was === pinned) return;
    cancelFold();
    const slot = slotRef.current;
    const spacer = spacerRef.current;
    if (!slot || !spacer || reduced || !canAnimate(slot) || !canAnimate(spacer)) {
      setTransient(null);
      return;
    }
    const finish = () => setTransient(null);
    if (!pinned) {
      setTransient("collapsing");
      const fold = slot.animate([{ width: `${panelWidth}px` }, { width: "0px" }], { duration: FOLD_MS, easing: EASE, fill: "forwards" });
      fold.onfinish = finish;
      foldAnimations.current = [fold];
      return;
    }
    if (peekRef.current) {
      setTransient("expanding-peek");
      const grow = spacer.animate([{ width: "0px" }, { width: `${panelWidth}px` }], { duration: FOLD_MS, easing: EASE, fill: "forwards" });
      grow.onfinish = finish;
      foldAnimations.current = [grow];
      const shadow = shadowRef.current;
      if (canAnimate(shadow)) foldAnimations.current.push(shadow.animate([{ opacity: 1 }, { opacity: 0 }], { duration: FOLD_MS, easing: "ease-out", fill: "forwards" }));
      return;
    }
    setTransient("expanding-closed");
    const unfold = slot.animate([{ width: "0px" }, { width: `${panelWidth}px` }], { duration: FOLD_MS, easing: EASE, fill: "forwards" });
    unfold.onfinish = finish;
    foldAnimations.current = [unfold];
  }, [pinned]);

  React.useLayoutEffect(() => {
    const was = previousPeek.current;
    previousPeek.current = peeking;
    if (was === peeking || pinned) return;
    const slot = slotRef.current;
    if (!slot || reduced || !canAnimate(slot)) return;
    if (transient !== null && transient !== "peek-closing") return;
    cancelFold();
    if (peeking) {
      if (transient === "peek-closing") setTransient(null);
      foldAnimations.current = [slot.animate(
        [{ transform: "translateX(-8px)", opacity: 0 }, { transform: "translateX(0)", opacity: 1 }],
        { duration: PEEK_MS, easing: EASE_OUT },
      )];
      return;
    }
    setTransient("peek-closing");
    const retract = slot.animate(
      [{ transform: "translateX(0)", opacity: 1 }, { transform: "translateX(-8px)", opacity: 0 }],
      { duration: PEEK_MS, easing: EASE, fill: "forwards" },
    );
    retract.onfinish = () => setTransient(null);
    foldAnimations.current = [retract];
  }, [peeking]);

  // Once a steady state is rendered the forward-filled animations are no longer needed: the inline styles now describe the same geometry.
  React.useLayoutEffect(() => {
    if (transient !== null) return;
    cancelFold();
  }, [transient]);

  React.useLayoutEffect(() => {
    peekRef.current = peeking;
  });

  const sectionKey = sections.map((section) => section.id).join("|");
  React.useEffect(() => {
    const list = listRef.current;
    if (!list || typeof ResizeObserver === "undefined") return;
    const observer = new ResizeObserver(() => {
      const button = buttonRefs.current[previousActive.current];
      if (!button) return;
      slideAnimation.current?.cancel();
      placeIndicator(button);
    });
    observer.observe(list);
    return () => observer.disconnect();
  }, [sectionKey]);

  React.useEffect(() => {
    if (!peeking) return;
    const onPointerDown = (event: PointerEvent) => {
      const aside = asideRef.current;
      if (aside && event.target instanceof Node && !aside.contains(event.target)) closePeek();
    };
    document.addEventListener("pointerdown", onPointerDown);
    return () => document.removeEventListener("pointerdown", onPointerDown);
  }, [peeking]);

  React.useEffect(() => () => {
    clearCloseTimer();
    slideAnimation.current?.cancel();
    cancelFold();
  }, []);

  const onRailKeyDown = (event: React.KeyboardEvent) => {
    const ids = sections.map((section) => section.id);
    if (ids.length === 0) return;
    const target = event.target instanceof HTMLElement ? event.target.dataset.sectionButton : undefined;
    const current = Math.max(0, ids.indexOf(target ?? active));
    let next = -1;
    if (event.key === "ArrowDown") next = (current + 1) % ids.length;
    else if (event.key === "ArrowUp") next = (current - 1 + ids.length) % ids.length;
    else if (event.key === "Home") next = 0;
    else if (event.key === "End") next = ids.length - 1;
    if (next < 0) return;
    event.preventDefault();
    buttonRefs.current[ids[next]!]?.focus();
  };

  const onAsideKeyDown = (event: React.KeyboardEvent) => {
    if (event.key !== "Escape" || !peeking) return;
    event.preventDefault();
    closePeek();
    buttonRefs.current[active]?.focus();
  };

  const onAsideFocus = (event: React.FocusEvent) => {
    if (pinned) return;
    if (event.target instanceof HTMLElement && event.target.matches(":focus-visible")) openPeek();
  };

  const onAsideBlur = (event: React.FocusEvent) => {
    if (pinned) return;
    const next = event.relatedTarget;
    if (!(next instanceof Node) || !asideRef.current?.contains(next)) scheduleClose();
  };

  const togglePin = () => {
    const next = !pinned;
    setPinnedState(next);
    if (!next) buttonRefs.current[active]?.focus();
  };

  const slotVisible = pinned || peeking || transient !== null;
  const slotDocked = (pinned && transient !== "expanding-peek") || transient === "collapsing";
  const shadowOn = peeking || transient === "expanding-peek" || transient === "peek-closing";
  const context: RailPanelContext = { id: active, pinned, peeking, query, closePeek };
  const renderPanel = (section: RailPanelSection | undefined, panelContext: RailPanelContext) => {
    if (!section) return null;
    return typeof section.panel === "function" ? section.panel(panelContext) : section.panel;
  };

  const slotStyle: React.CSSProperties = slotDocked
    ? { width: panelWidth }
    : { left: railWidth, width: panelWidth, visibility: slotVisible ? "visible" : "hidden" };

  return (
    <div
      ref={ref}
      data-slot="rail-panel-sidebar"
      data-active={active}
      data-pinned={pinned ? "true" : "false"}
      data-peeking={peeking ? "true" : "false"}
      data-transient={transient ?? "none"}
      className={`isolate grid h-full min-h-0 w-full grid-cols-[auto_minmax(0,1fr)] bg-background text-foreground ${className}`}
      style={style}
      {...rest}
    >
      <aside
        ref={asideRef}
        aria-label={labels?.sidebar ?? "Sidebar"}
        className="relative z-20 flex h-full min-h-0"
        onPointerEnter={(event) => { if (event.pointerType !== "touch" && !pinned) openPeek(); }}
        onPointerLeave={(event) => { if (event.pointerType !== "touch" && !pinned) scheduleClose(); }}
        onFocus={onAsideFocus}
        onBlur={onAsideBlur}
        onKeyDown={onAsideKeyDown}
      >
        <nav
          aria-label={labels?.sections ?? "Sections"}
          data-rail
          style={{ width: railWidth }}
          className="relative flex h-full shrink-0 flex-col items-center border-r border-border bg-card py-3"
        >
          {brand !== undefined && <div data-brand className="mb-3 flex h-8 items-center justify-center">{brand}</div>}
          <div ref={listRef} role="list" onKeyDown={onRailKeyDown} className="relative flex w-full flex-col items-center gap-1 px-2">
            <span ref={indicatorRef} data-indicator aria-hidden="true" className="pointer-events-none absolute left-0 top-0 h-10 w-full will-change-transform">
              <span className="absolute left-0 top-1/2 h-5 w-0.5 -translate-y-1/2 rounded-r-full bg-primary" />
              <span className="absolute inset-y-0 left-2 right-2 rounded-lg bg-muted" />
            </span>
            {sections.map((section) => {
              const selected = section.id === active;
              return (
                <div key={section.id} role="listitem" className="flex">
                  <button
                    ref={(node) => { buttonRefs.current[section.id] = node; }}
                    type="button"
                    data-section-button={section.id}
                    data-state={selected ? "active" : "inactive"}
                    aria-label={section.label}
                    aria-current={selected ? "page" : undefined}
                    tabIndex={selected ? 0 : -1}
                    onClick={() => { selectSection(section.id); if (!pinned) openPeek(); }}
                    className={`relative z-10 flex size-10 items-center justify-center rounded-lg outline-none transition-colors duration-200 motion-reduce:transition-none hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring ${selected ? "text-foreground" : "text-muted-foreground hover:bg-muted/50"}`}
                  >
                    <span className="[&>svg]:size-5" aria-hidden="true">{section.icon}</span>
                    {section.badge !== undefined && (
                      <span data-badge className="absolute right-1 top-1 flex h-4 min-w-4 items-center justify-center rounded-full bg-primary px-1 font-mono text-[10px] leading-none tabular-nums text-primary-foreground">
                        {section.badge}
                      </span>
                    )}
                  </button>
                </div>
              );
            })}
          </div>
          {footer !== undefined && <div data-footer className="mt-auto flex flex-col items-center gap-2 pt-3">{footer}</div>}
        </nav>
        <div ref={spacerRef} aria-hidden="true" data-spacer className="h-full shrink-0" style={{ width: 0 }} />
        <div
          ref={slotRef}
          role="region"
          aria-labelledby={titleId}
          aria-hidden={slotVisible ? undefined : "true"}
          data-panel
          data-docked={slotDocked ? "true" : "false"}
          style={slotStyle}
          className={`isolate border-r border-border bg-background ${slotDocked ? "relative h-full shrink-0 overflow-hidden" : "absolute inset-y-0"}`}
        >
          <div ref={shadowRef} aria-hidden="true" data-shadow style={{ opacity: shadowOn ? 1 : 0 }} className="pointer-events-none absolute inset-0 -z-10 shadow-2xl shadow-foreground/25 dark:shadow-background/90 dark:ring-1 dark:ring-foreground/10" />
          <div className="flex h-full flex-col" style={{ width: panelWidth }}>
            <header className="flex h-12 shrink-0 items-center justify-between pl-4 pr-2">
              <h2 key={active} id={titleId} data-title className="truncate text-sm font-semibold tracking-tight">{activeSection?.label}</h2>
              <button
                type="button"
                data-pin
                aria-pressed={pinned}
                aria-label={labels?.pin ?? "Pin panel"}
                onClick={togglePin}
                className={`flex size-8 shrink-0 items-center justify-center rounded-lg outline-none transition-colors duration-200 motion-reduce:transition-none hover:bg-muted hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring ${pinned ? "text-foreground" : "text-muted-foreground"}`}
              >
                {pinned ? <Pin className="size-4" aria-hidden="true" /> : <PinOff className="size-4" aria-hidden="true" />}
              </button>
            </header>
            {search && (
              <div className="shrink-0 px-3 pb-2">
                <label className="relative block">
                  <Search className="pointer-events-none absolute left-2.5 top-1/2 size-3.5 -translate-y-1/2 text-muted-foreground" aria-hidden="true" />
                  <input
                    type="search"
                    data-search
                    value={query}
                    onChange={(event) => setQuery(event.target.value)}
                    placeholder={activeSection?.searchPlaceholder ?? labels?.search ?? "Search"}
                    aria-label={activeSection?.searchPlaceholder ?? labels?.search ?? "Search"}
                    className="h-8 w-full rounded-lg bg-muted/60 pl-8 pr-2 text-sm outline-none transition-colors motion-reduce:transition-none placeholder:text-muted-foreground focus-visible:ring-2 focus-visible:ring-ring"
                  />
                </label>
              </div>
            )}
            <div ref={bodyRef} className="relative min-h-0 flex-1 overflow-y-auto overflow-x-hidden">
              <div key={active} data-entering data-section={active} className="px-2 pb-2">
                {renderPanel(activeSection, context)}
              </div>
              {leaving && leavingSection && (
                <div key={leaving.id} data-leaving aria-hidden="true" className="pointer-events-none absolute inset-0 px-2 pb-2">
                  {renderPanel(leavingSection, { ...context, id: leaving.id, query: "" })}
                </div>
              )}
            </div>
          </div>
        </div>
        <span className="sr-only" role="status">{activeSection ? `${activeSection.label} panel` : ""}</span>
      </aside>
      <div data-content className="relative z-0 min-h-0 min-w-0 overflow-auto">{children}</div>
    </div>
  );
}

export default RailPanelSidebar;

