type Step = { at: number; run: () => void };

export default function Demo({ autoplay = true }: DemoProps) {
  const params = React.useMemo(() => new URLSearchParams(typeof window === "undefined" ? "" : window.location.search), []);
  const controlled = params.get("controlled") === "1";
  const [active, setActive] = React.useState("home");
  const [pinned, setPinned] = React.useState(true);
  const [peeking, setPeeking] = React.useState(false);
  const [requests, setRequests] = React.useState([] as string[]);
  const [motion, setMotion] = React.useState({ ready: false, reduced: true });
  const [paused, setPaused] = React.useState(false);
  const [compact, setCompact] = React.useState(false);
  const [run, setRun] = React.useState(0);
  const rootRef = React.useRef(null as HTMLElement | null);

  React.useEffect(() => {
    const media = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setMotion({ ready: true, reduced: media.matches });
    update();
    media.addEventListener("change", update);
    return () => media.removeEventListener("change", update);
  }, []);

  React.useEffect(() => {
    const media = window.matchMedia("(max-width: 639px)");
    const update = () => setCompact(media.matches);
    update();
    media.addEventListener("change", update);
    return () => media.removeEventListener("change", update);
  }, []);

  React.useEffect(() => {
    if (!motion.ready || !autoplay || motion.reduced || paused || controlled) return;
    const root = rootRef.current;
    const started = performance.now();
    let count = 0;
    if (root) {
      root.dataset.tourStarted = started.toFixed(1);
      root.dataset.tourStep = "0";
    }
    const script: Step[] = [
      { at: 600, run: () => setActive("projects") },
      { at: 2200, run: () => setActive("inbox") },
      { at: 3600, run: () => setPinned(false) },
      { at: 5000, run: () => setPeeking(true) },
      { at: 6200, run: () => setPeeking(false) },
      { at: 8000, run: () => setPinned(true) },
      { at: 8800, run: () => setActive("home") },
    ];
    const timers = script.map((step) => window.setTimeout(() => {
      step.run();
      count += 1;
      if (root) {
        root.dataset.tourStep = String(count);
        root.dataset.tourLastAt = performance.now().toFixed(1);
      }
    }, step.at));
    timers.push(window.setTimeout(() => setRun((previous) => previous + 1), 10000));
    return () => timers.forEach((timer) => window.clearTimeout(timer));
  }, [motion.ready, motion.reduced, autoplay, paused, controlled, run]);

  const takeOver = () => autoplay && setPaused(true);
  const note = (entry: string) => setRequests((previous) => [...previous, entry]);

  return (
    <main
      ref={rootRef}
      data-demo="rail-panel-sidebar"
      className="w-full bg-background p-4 text-foreground"
      style={{ height: "min(100svh, 792px)" }}
      onPointerDownCapture={takeOver}
      onKeyDownCapture={takeOver}
    >
      <RailPanelSidebar
        sections={SECTIONS}
        activeId={controlled ? "home" : active}
        onActiveChange={(id) => (controlled ? note(`active:${id}`) : setActive(id))}
        pinned={controlled ? true : pinned}
        onPinnedChange={(next) => (controlled ? note(`pinned:${next}`) : setPinned(next))}
        peeking={peeking}
        onPeekingChange={setPeeking}
        width={{ rail: 56, panel: compact ? 212 : 248 }}
        brand={<Brand />}
        footer={
          <button type="button" aria-label="Account" className="rounded-full outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-card">
            <Avatar person={PEOPLE.felix} size="size-8" />
          </button>
        }
        className="h-full overflow-hidden rounded-2xl shadow-sm ring-1 ring-border"
      >
        <Placeholder />
      </RailPanelSidebar>
      {controlled && <output data-requests className="sr-only">{requests.join(" ")}</output>}
    </main>
  );
}
